98	    /**
99	     * The id of the existing owner this owner soft-matches, set together with
100	     * {@link #isPossibleDuplicate()} when a soft match is detected; {@code null} otherwise.
101	     */
102	    @Column(name = "possible_duplicate_of")
103	    private Integer possibleDuplicateOf;
