105	    /**
106	     * Whether this owner has been soft-deleted. A newly created owner is {@code false}; deleting an
107	     * owner (DELETE /api/owners/{id}) flags this {@code true} and retains the row instead of removing
108	     * it. Deleted owners are ignored by the create endpoint's duplicate and identity checks.
109	     */
110	    @Column(name = "deleted")
111	    private boolean deleted;
112	
113	    /**
114	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}, captured
115	     * when the owner was created: a new owner's level may not exceed one above the highest level
116	     * among the household members that already existed at creation time. {@code null} when no cap
117	     * applies (the owner belonged to no existing household member when created), in which case the
118	     * membership level is returned uncapped.
119	     */
120	    @Column(name = "membership_level_cap")
121	    private Integer membershipLevelCap;
