312	    /** The household size at or above which an owner earns the household membership points. */
313	    public static final int MEMBERSHIP_HOUSEHOLD_SIZE = 3;
314	
315	    /** The month (1 July) on which the fiscal year begins. */
316	    public static final int FISCAL_YEAR_START_MONTH = 7;
317	
318	    /**
319	     * The number of elapsed fiscal years at or above which an owner earns the tenure membership
320	     * points.
321	     */
322	    public static final long MEMBERSHIP_TENURE_FISCAL_YEARS = 1;
323	
324	    /**
325	     * The fiscal year (as a full four-digit number) that {@code date} falls in, where the fiscal
326	     * year begins on 1 July and is labelled by the calendar year in which it ends: a date on or
327	     * after 1 July belongs to the next calendar year's fiscal year.
328	     */
329	    public static int fiscalYearOf(LocalDate date) {
330	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
331	    }
332	
333	    /**
334	     * The fiscal year of the owner's (business-day-adjusted) {@code registrationDate}, formatted
335	     * {@code 'FY<YY>'} where YY is the last two digits of the fiscal year (see
336	     * {@link #fiscalYearOf(LocalDate)}). Null when no registration date is set.
337	     */
338	    public String getFiscalYear() {
339	        if (this.registrationDate == null) {
340	            return null;
341	        }
342	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
343	    }
344	
345	    /**
346	     * The owner's membership points, computed from stored fields: they start at 0, gain 2 when an
347	     * email is present, gain 1 when {@code namesakeCount} is 0, gain 2 for a household of
348	     * {@value #MEMBERSHIP_HOUSEHOLD_SIZE} or more (see {@link #getHouseholdSize()}), and gain 3 when
349	     * the owner's tenure (fiscal years elapsed since its {@code registrationDate}) is at least
350	     * {@value #MEMBERSHIP_TENURE_FISCAL_YEARS}.
351	     */
352	    public int getMembershipPoints() {
353	        int points = 0;
354	        if (this.email != null && !this.email.isEmpty()) {
355	            points += 2;
356	        }
357	        if (this.namesakeCount != null && this.namesakeCount == 0) {
358	            points += 1;
359	        }
360	        if (this.householdSize >= MEMBERSHIP_HOUSEHOLD_SIZE) {
361	            points += 2;
362	        }
363	        if (this.registrationDate != null
364	                && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate))
365	                        >= MEMBERSHIP_TENURE_FISCAL_YEARS) {
366	            points += 3;
367	        }
368	        return points;
369	    }
370	
371	    /**
372	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()}: 1 for 0-1
373	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points, then capped by the
374	     * {@link #getMembershipLevelCap() membership level cap} when one was captured at creation time.
375	     */
376	    public int getMembershipLevel() {
377	        int level = computeMembershipLevel();
378	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
379	            return this.membershipLevelCap;
380	        }
381	        return level;
382	    }
383	
384	    /**
385	     * The uncapped membership level derived purely from {@link #getMembershipPoints()}: 1 for 0-1
386	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
387	     */
388	    private int computeMembershipLevel() {
389	        int points = getMembershipPoints();
390	        if (points >= 6) {
391	            return 4;
392	        }
393	        if (points >= 4) {
394	            return 3;
395	        }
396	        if (points >= 2) {
397	            return 2;
398	        }
399	        return 1;
400	    }
401	
402	    public Integer getMembershipLevelCap() {
403	        return this.membershipLevelCap;
404	    }
