410	    /**
411	     * The derived identity key used to detect duplicate owners: the lower-case SHA-256 hex digest
412	     * over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the
413	     * telephone is already normalized to E.164 and the email is lower-cased. Two owners are
414	     * duplicates only when their whole identity keys are equal. Because the telephone is part of the
415	     * key, two owners with the same {@code lastName} and {@code postcode} but different telephones
416	     * have different keys and are both allowed (they are instead flagged as a soft match).
417	     */
418	    public String getIdentityKey() {
419	        String tel = this.telephone == null ? "" : this.telephone;
420	        String mail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
421	        String soundex = Soundex.encode(this.getLastName());
422	        return Sha256Hex.lowerHex(tel + "|" + mail + "|" + soundex);
423	    }
424	
425	    /**
426	     * A single Luhn check digit (0-9) computed over the digits contained in {@code customerCode},
427	     * or null when the {@code customerCode} has not been assigned.
428	     */
429	    public Integer getCheckDigit() {
430	        if (this.customerCode == null) {
431	            return null;
432	        }
433	        int sum = 0;
434	        boolean dbl = true;
435	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
436	            char c = this.customerCode.charAt(i);
437	            if (c < '0' || c > '9') {
438	                continue;
439	            }
440	            int d = c - '0';
441	            if (dbl) {
442	                d *= 2;
443	                if (d > 9) {
444	                    d -= 9;
445	                }
446	            }
447	            sum += d;
448	            dbl = !dbl;
449	        }
450	        return (10 - (sum % 10)) % 10;
451	    }
452	
453	    /**
454	     * The owner's membership number formatted {@code '<customerCode>-M<YY>'} where YY is the last
455	     * two digits of the fiscal year of the {@code registrationDate} (see
456	     * {@link #fiscalYearOf(LocalDate)}), or null when either the {@code customerCode} or the
457	     * {@code registrationDate} is not set.
458	     */
459	    public String getMembershipNumber() {
460	        if (this.customerCode == null || this.registrationDate == null) {
461	            return null;
462	        }
463	        String yy = String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
464	        return this.customerCode + "-M" + yy;
465	    }
