519	    /**
520	     * Return the Pet with the given name, or null if none found for this Owner.
521	     *
522	     * @param name to test
523	     * @return true if pet name is already in use
524	     */
525	    public Pet getPet(String name, boolean ignoreNew) {
526	        name = name.toLowerCase();
527	        for (Pet pet : getPetsInternal()) {
528	            if (!ignoreNew || !pet.isNew()) {
529	                String compName = pet.getName();
530	                compName = compName.toLowerCase();
531	                if (compName.equals(name)) {
532	                    return pet;
533	                }
534	            }
535	        }
536	        return null;
537	    }
