543	    @Override
544	    public String toString() {
545	        return new ToStringCreator(this)
546	
547	            .append("id", this.getId())
548	            .append("new", this.isNew())
549	            .append("lastName", this.getLastName())
550	            .append("firstName", this.getFirstName())
551	            .append("address", this.address)
552	            .append("city", this.city)
553	            .append("telephone", this.telephone)
554	            .toString();
555	    }
