16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	
20	/**
21	 * Single source of truth for the fixed city-to-region mapping (Sydney->NSW, Melbourne->VIC,
22	 * Brisbane->QLD). Consumed by presentation (an owner's {@code locality}) and by validation (an
23	 * owner's postcode range), so both layers agree on which region a city belongs to.
24	 */
25	public final class Region {
26	
27	    /** Locality reported for a city that has no known region. */
28	    public static final String UNKNOWN = "UNKNOWN";
29	
30	    /** Fixed city-to-region lookup. */
31	    private static final Map<String, String> CITY_REGION = Map.of(
32	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
33	
34	    /** Region -> inclusive 4-digit postcode range {low, high}. */
35	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
36	        "NSW", new int[] {2000, 2099},
37	        "VIC", new int[] {3000, 3099},
38	        "QLD", new int[] {4000, 4099});
39	
40	    /** Fixed region-to-timezone lookup, as IANA names. */
41	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
42	        "NSW", "Australia/Sydney",
43	        "VIC", "Australia/Melbourne",
44	        "QLD", "Australia/Brisbane");
45	
46	    private Region() {
47	    }
48	
49	    /**
50	     * The canonical region for {@code city}, or {@code null} when the city has no known region.
51	     */
52	    public static String forCity(String city) {
53	        return CITY_REGION.get(city);
54	    }
55	
56	    /**
57	     * The canonical region whose range contains the given 4-digit {@code postcode}, or {@code null}
58	     * when the postcode is absent, not a number, or falls in no known range.
59	     */
60	    public static String forPostcode(String postcode) {
61	        if (postcode == null) {
62	            return null;
63	        }
64	        int value;
65	        try {
66	            value = Integer.parseInt(postcode.trim());
67	        } catch (NumberFormatException e) {
68	            return null;
69	        }
70	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
71	            int[] range = entry.getValue();
72	            if (value >= range[0] && value <= range[1]) {
73	                return entry.getKey();
74	            }
75	        }
76	        return null;
77	    }
78	
79	    /**
80	     * The inclusive 4-digit postcode range {@code {low, high}} for {@code region}, or {@code null}
81	     * when the region has no defined range. Returns a fresh array so callers cannot mutate the table.
82	     */
83	    public static int[] postcodeRange(String region) {
84	        int[] range = REGION_POSTCODES.get(region);
85	        return range == null ? null : new int[] {range[0], range[1]};
86	    }
87	
88	    /**
89	     * The canonical region for {@code city}, or {@link #UNKNOWN} when the city has no known region.
90	     */
91	    public static String localityForCity(String city) {
92	        String region = forCity(city);
93	        return region == null ? UNKNOWN : region;
94	    }
95	
96	    /**
97	     * The canonical region derived from the given 4-digit {@code postcode} (see
98	     * {@link #forPostcode(String)}), or {@link #UNKNOWN} when the postcode is absent or falls in no
99	     * known range. This is the {@code <REGION>} component of an owner's {@code customerCode}.
100	     */
101	    public static String regionForPostcode(String postcode) {
102	        String region = forPostcode(postcode);
103	        return region == null ? UNKNOWN : region;
104	    }
105	
106	    /**
107	     * The {@code <REGION>} component of a {@code customerCode} formatted {@code '<REGION>-<HASH8>'}
108	     * — the text before the first {@code '-'} — or {@link #UNKNOWN} when {@code customerCode} is
109	     * {@code null}, blank, or carries no separator. The matching layout is produced by
110	     * {@code ClinicServiceImpl.generateCustomerCode}; keep the two in sync.
111	     */
112	    public static String regionOfCustomerCode(String customerCode) {
113	        if (customerCode == null || customerCode.isBlank()) {
114	            return UNKNOWN;
115	        }
116	        int dash = customerCode.indexOf('-');
117	        return dash <= 0 ? UNKNOWN : customerCode.substring(0, dash);
118	    }
119	
120	    /**
121	     * The IANA timezone name for {@code region} via the fixed region-to-timezone table
122	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null}
123	     * when the region has no mapped timezone (e.g. {@link #UNKNOWN} or {@code null}).
124	     */
125	    public static String timezoneForRegion(String region) {
126	        return REGION_TIMEZONE.get(region);
127	    }
128	
129	    /**
130	     * The canonical region derived by preferring the {@code postcode} range, and only falling back
131	     * to the city-to-region table when the postcode is absent or in no known range. Returns
132	     * {@link #UNKNOWN} when neither the postcode nor the city yields a region.
133	     */
134	    public static String locality(String city, String postcode) {
135	        String region = forPostcode(postcode);
136	        if (region == null) {
137	            region = forCity(city);
138	        }
139	        return region == null ? UNKNOWN : region;
140	    }
141	}
